#!/usr/bin/env bash
# Fix: License Excel import failing on every row when Purchase/Expiry Date
# are genuine Excel date-typed cells (read as raw serial numbers, not dates).
# Generated by gen_deploy_license_date_cell_fix.py - do not hand-edit.
#
# No ordering dependency - this file is untouched by every other outstanding
# or already-deployed script this session.
#
# Run this from the repo root on the server.
set -uo pipefail

sec() { echo ""; echo "=== $* ==="; echo "=== $* ===" >&2; }

FAIL=0

sec "0. Confirm repo root"
if [ ! -d "frontend/lib/utils" ]; then
    echo "!!! Expected directories not found under $(pwd) - run this from the repo root."
    exit 1
fi

sec "1. Pre-flight: verify every touched file is exactly what was confirmed"
if [ ! -f "frontend/lib/utils/license-excel.ts" ]; then
    echo "!!! frontend/lib/utils/license-excel.ts not found - aborting, nothing written yet."
    FAIL=1
else
    h=$(git hash-object "frontend/lib/utils/license-excel.ts")
    if [ "$h" != "d2abe249654c6573f282d06c1c3bda9d9b056ee1" ]; then
        echo "!!! frontend/lib/utils/license-excel.ts does not match the expected pre-deploy hash."
        echo "    expected: d2abe249654c6573f282d06c1c3bda9d9b056ee1"
        echo "    actual:   $h"
        echo "    This file has changed on the server since it was last verified - do not proceed."
        FAIL=1
    fi
fi

if [ "$FAIL" != "0" ]; then
    echo ""
    echo ">>> Pre-flight checks failed - nothing was written. See messages above."
    exit 1
fi
echo "All pre-flight checks passed."

sec "2. Writing files"
mkdir -p "$(dirname "frontend/lib/utils/license-excel.ts")"
base64 -d > "frontend/lib/utils/license-excel.ts.tmp" <<'B64EOF'

B64EOF
mv "frontend/lib/utils/license-excel.ts.tmp" "frontend/lib/utils/license-excel.ts"
echo "wrote frontend/lib/utils/license-excel.ts"

sec "3. Post-flight: verify every written file matches the expected final hash"
POSTFAIL=0
h=$(git hash-object "frontend/lib/utils/license-excel.ts")
if [ "$h" != "29c16cbce3eb24513c8ea3561b420afd4ad9a8bc" ]; then
    echo "!!! frontend/lib/utils/license-excel.ts does not match the expected post-deploy hash (expected 29c16cbce3eb24513c8ea3561b420afd4ad9a8bc, got $h)"
    POSTFAIL=1
else
    echo "OK: frontend/lib/utils/license-excel.ts"
fi

if [ "$POSTFAIL" != "0" ]; then
    echo ""
    echo ">>> Post-deploy verification failed - do not restart the containers; investigate before proceeding."
    exit 1
fi

sec "4. Done"
echo "Files written and verified. Next steps:"
echo "  1. git add -A && git commit  (commit this on the server's own checkout)"
echo "  2. docker compose build frontend && docker compose up -d frontend"
echo "     (frontend-only, no migration, no backend change)"
echo "  3. Re-attempt your real License import (the one that previously failed on"
echo "     every row with a DateTime conversion error) - it should now succeed"
echo "  4. If you still see any per-row failures, they'll now be a different,"
echo "     genuine reason (e.g. Software not in the Software Catalog) - not this bug"
echo ">>> DONE"
